UPDATE oa_contract SET owner_id = #{contract.ownerId}, owner_name = #{contract.ownerName},
    dept_id = #{contract.deptId}, dept_name = #{contract.deptName}, version = version + 1,
    update_by = #{contract.updateBy}, update_time = #{contract.updateTime}
WHERE contract_id = #{contract.contractId} AND tenant_id = #{contract.tenantId} AND deleted = 0 AND version = #{expectedVersion}

UPDATE oa_contract SET deleted = 1, version = version + 1,
    update_by = #{contract.updateBy}, update_time = #{contract.updateTime}
WHERE contract_id = #{contract.contractId} AND tenant_id = #{contract.tenantId}
    AND deleted = 0 AND version = #{contract.version}
